# --- benchmark ---
import json
seen = set()
totals = {}
duplicates = 0
malformed = 0
for line in TEXT.splitlines():
    try:
        row = json.loads(line)
    except ValueError:
        malformed += 1
        continue
    event_id = row['id']
    if event_id in seen:
        duplicates += 1
        continue
    seen.add(event_id)
    team = row['team']
    totals[team] = totals.get(team, 0) + row['amount_cents']
output = []
for team in sorted(totals):
    output.append(json.dumps({'team': team, 'amount_cents': totals[team]}, sort_keys=True))
print(duplicates, malformed, len(seen))
print('\n'.join(output))
